static MODES: [Mode; 1] = [
    Mode { class: &M0_CLASS, trans: &M0_TRANS, accept: &M0_ACCEPT, start: 53, accept_from: 1113 },
];

/// What the lexer could not do at the error position.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LexErrorReason {
    /// No rule matches.
    NoMatch,
    /// A rule matches, but its value does not fit the Rust type (a numeral beyond `u64`).
    Unrepresentable,
    /// End of input inside a nested mode.
    EndInMode,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct LexError {
    /// Character offset, as in Lean's `LexError.pos`.
    pub pos: usize,
    /// Byte offset.
    pub byte_pos: usize,
    /// The offending character; none at end of input.
    pub ch: Option<char>,
    pub reason: LexErrorReason,
}

fn lex_error(src: &str, byte_pos: usize, reason: LexErrorReason) -> LexError {
    LexError {
        pos: src[..byte_pos].chars().count(),
        byte_pos,
        ch: src[byte_pos..].chars().next(),
        reason,
    }
}

/// The longest match from `pos`: the accepting rule plus one (0 for none) and its end.
#[inline(always)]
fn scan(mode: &Mode, src: &[u8], pos: usize) -> (usize, usize) {
    let mut row = mode.start;
    let mut i = pos;
    let mut best = 0usize;
    let mut end = pos;
    loop {
        if row >= mode.accept_from {
            best = row;
            end = i;
        }
        if i >= src.len() {
            break;
        }
        let next = mode.trans[row + mode.class[src[i] as usize] as usize] as usize;
        if next == 0 {
            break;
        }
        i += 1;
        if next == row {
            // A self-loop (a run of identifier characters, of spaces, …): the loads of
            // the following bytes do not depend on each other, so scan the run apart.
            while i < src.len()
                && mode.trans[row + mode.class[src[i] as usize] as usize] as usize == row
            {
                i += 1;
            }
        } else {
            row = next;
        }
    }
    (mode.accept[best] as usize, end)
}

/// Longest-match tokenization of `src`, appending to `out` (which is not cleared).
/// The last token pushed is the end-of-input token.
pub fn tokenize<'a>(src: &'a str, out: &mut Vec<Spanned<Tok<'a>>>) -> Result<(), LexError> {
    let bytes = src.as_bytes();
    let n = bytes.len();
    let mut pos = 0usize;
    while pos < n {
        let mode = 0;
        let (rule, end) = scan(&MODES[mode], bytes, pos);
        if rule == 0 || end == pos {
            return Err(lex_error(src, pos, LexErrorReason::NoMatch));
        }
        let r = rule - 1;
        let text = &src[pos..end];
        match mode {
            0 => match r {
                2 => out.push(Spanned { tok: Tok::PRINCIPAL_SLOT, start: pos as u32, end: end as u32 }),
                3 => out.push(Spanned { tok: Tok::RESOURCE_SLOT, start: pos as u32, end: end as u32 }),
                4 => out.push(Spanned { tok: Tok::OTHER_SLOT(text), start: pos as u32, end: end as u32 }),
                5 => match crate::hooks::keyword_or_identifier(text) { Some(tok) => out.push(Spanned { tok, start: pos as u32, end: end as u32 }), None => return Err(lex_error(src, pos, LexErrorReason::Unrepresentable)) },
                6 => match lexrt::to_nat(text) { Some(v) => out.push(Spanned { tok: Tok::NUMBER(v), start: pos as u32, end: end as u32 }), None => return Err(lex_error(src, pos, LexErrorReason::Unrepresentable)) },
                7 => match crate::hooks::strip_string_quotes(text) { Some(v) => out.push(Spanned { tok: Tok::STRINGLIT(v), start: pos as u32, end: end as u32 }), None => return Err(lex_error(src, pos, LexErrorReason::Unrepresentable)) },
                8 => out.push(Spanned { tok: Tok::EQ, start: pos as u32, end: end as u32 }),
                9 => out.push(Spanned { tok: Tok::NEQ, start: pos as u32, end: end as u32 }),
                10 => out.push(Spanned { tok: Tok::LEQ, start: pos as u32, end: end as u32 }),
                11 => out.push(Spanned { tok: Tok::GEQ, start: pos as u32, end: end as u32 }),
                12 => out.push(Spanned { tok: Tok::OR, start: pos as u32, end: end as u32 }),
                13 => out.push(Spanned { tok: Tok::AND, start: pos as u32, end: end as u32 }),
                14 => out.push(Spanned { tok: Tok::COLONCOLON, start: pos as u32, end: end as u32 }),
                15 => out.push(Spanned { tok: Tok::AT, start: pos as u32, end: end as u32 }),
                16 => out.push(Spanned { tok: Tok::DOT, start: pos as u32, end: end as u32 }),
                17 => out.push(Spanned { tok: Tok::COMMA, start: pos as u32, end: end as u32 }),
                18 => out.push(Spanned { tok: Tok::SEMICOLON, start: pos as u32, end: end as u32 }),
                19 => out.push(Spanned { tok: Tok::COLON, start: pos as u32, end: end as u32 }),
                20 => out.push(Spanned { tok: Tok::LPAREN, start: pos as u32, end: end as u32 }),
                21 => out.push(Spanned { tok: Tok::RPAREN, start: pos as u32, end: end as u32 }),
                22 => out.push(Spanned { tok: Tok::LBRACE, start: pos as u32, end: end as u32 }),
                23 => out.push(Spanned { tok: Tok::RBRACE, start: pos as u32, end: end as u32 }),
                24 => out.push(Spanned { tok: Tok::LBRACKET, start: pos as u32, end: end as u32 }),
                25 => out.push(Spanned { tok: Tok::RBRACKET, start: pos as u32, end: end as u32 }),
                26 => out.push(Spanned { tok: Tok::LT, start: pos as u32, end: end as u32 }),
                27 => out.push(Spanned { tok: Tok::GT, start: pos as u32, end: end as u32 }),
                28 => out.push(Spanned { tok: Tok::PLUS, start: pos as u32, end: end as u32 }),
                29 => out.push(Spanned { tok: Tok::MINUS, start: pos as u32, end: end as u32 }),
                30 => out.push(Spanned { tok: Tok::STAR, start: pos as u32, end: end as u32 }),
                31 => out.push(Spanned { tok: Tok::SLASH, start: pos as u32, end: end as u32 }),
                32 => out.push(Spanned { tok: Tok::PERCENT, start: pos as u32, end: end as u32 }),
                33 => out.push(Spanned { tok: Tok::BANG, start: pos as u32, end: end as u32 }),
                34 => out.push(Spanned { tok: Tok::SINGLE_EQ, start: pos as u32, end: end as u32 }),
                0 | 1 => {}
                _ => {}
            },
            _ => {}
        }
        pos = end;
    }
    out.push(Spanned { tok: Tok::EOF, start: n as u32, end: n as u32 });
    Ok(())
}

